$ok = 0; $manquants = @(); $differents = @()
foreach ($f in $attendus.Keys | Sort-Object) {
  $chemin = Join-Path $Racine $f
  if (-not (Test-Path $chemin)) { $manquants += $f; continue }
  $h = (Get-FileHash $chemin -Algorithm SHA256).Hash.ToLower()
  if ($h -eq $attendus[$f]) { $ok++ } else { $differents += $f }
}
Write-Host "$ok fichiers OK sur $($attendus.Count)" -ForegroundColor Green
if ($manquants.Count)  { Write-Host "`nMANQUANTS ($($manquants.Count)) :" -ForegroundColor Red; $manquants | ForEach-Object { '  ' + $_ } }
if ($differents.Count) { Write-Host "`nDIFFERENTS ($($differents.Count)) :" -ForegroundColor Yellow; $differents | ForEach-Object { '  ' + $_ } }
if (-not $manquants.Count -and -not $differents.Count) { Write-Host 'Le backend est complet et a jour.' -ForegroundColor Green }
